"""`@zuke/widget` 0.1.0: A command wrapper of every shape the Python facade generator must read: settings on core's base with its inherited setters, a kind-changing setter, a literal union behind a type alias, a rest parameter, an optional one, a union of keywords, a date, a setter of plain data, setters of a callback, a signal and a host the facade must leave out, a protected member, and a task object declared through an interface.

Generated by ``zuke pythonFacades`` from the wrapper's own documentation; edit
the wrapper in zuke-build/zuke, not this file.
"""

from __future__ import annotations

from collections.abc import Callable, Mapping
from typing import Literal, Self

from zuke import Context, ExecResult
from zuke._facade import call, configured, exec_result
from zuke.tools._tooling import ToolSettings

PACKAGE = "widget"
VERSION = "0.1.0"


class WidgetSettings(ToolSettings):
    """Settings for `widget build`."""

    def name(
        self,
        value: str,
    ) -> Self:
        """The widget to build (required)."""
        return self._record("name", value)

    def level(
        self,
        n: float,
    ) -> Self:
        """How much to say, 0 to 3 (`--level`)."""
        return self._record("level", n)

    def verbose(self) -> Self:
        """Say everything (`--verbose`)."""
        return self._record("verbose")

    def tags(
        self,
        *values: str,
    ) -> Self:
        """Tags to attach (`--tag`); repeatable."""
        return self._record("tags", *values)

    def format(
        self,
        kind: Literal["text", "json"],
    ) -> Self:
        """The output format (`--format`)."""
        return self._record("format", kind)

    def limit(
        self,
        value: str | float,
    ) -> Self:
        """Stop after this long, a duration or milliseconds (`--limit`)."""
        return self._record("limit", value)

    def strict(
        self,
        on: bool | None = None,
    ) -> Self:
        """Refuse a widget with warnings (`--strict`), on by default."""
        return self._record("strict", on)

    def since(
        self,
        time: str,
    ) -> Self:
        """Only changes after this time (`--since`), a date or its ISO string."""
        return self._record("since", time)

    def options(
        self,
        value: Mapping[str, object],
    ) -> Self:
        """The build's options, as plain data."""
        return self._record("options", value)

    def inspecting(self) -> WidgetInspectSettings:
        """Inspect instead of build: the inspect settings carry what is set so far."""
        return self._switch(WidgetInspectSettings, "inspecting")


class WidgetInspectSettings(WidgetSettings):
    """Settings for `widget inspect`."""

    def fields(
        self,
        *names: str,
    ) -> Self:
        """The fields to show (`--field`); all when none is named."""
        return self._record("fields", *names)


class WidgetTasks:
    """Typed task functions for the widget CLI."""

    @staticmethod
    async def build(
        ctx: Context,
        configure: Callable[[WidgetSettings], WidgetSettings] | None = None,
    ) -> ExecResult:
        """Build a widget: `widget build`."""
        answer = await call(
            ctx,
            PACKAGE,
            VERSION,
            "WidgetTasks",
            "build",
            [configured(WidgetSettings(), configure)],
        )
        return exec_result(answer)

    @staticmethod
    async def inspect(
        ctx: Context,
        name: str,
        configure: Callable[[WidgetInspectSettings], WidgetInspectSettings],
    ) -> object:
        """Inspect a widget by name: `widget inspect <name>`; answers its report."""
        return await call(
            ctx,
            PACKAGE,
            VERSION,
            "WidgetTasks",
            "inspect",
            [name, configured(WidgetInspectSettings(), configure)],
        )

    @staticmethod
    async def clean(
        ctx: Context,
        configure: Callable[[WidgetSettings], WidgetSettings] | None = None,
    ) -> None:
        """Remove a widget's build output: `widget clean`."""
        await call(
            ctx,
            PACKAGE,
            VERSION,
            "WidgetTasks",
            "clean",
            [configured(WidgetSettings(), configure)],
        )
